CREATE DATABASE IF NOT EXISTS nexus CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE nexus;
CREATE TABLE usuarios (id INT AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(150) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,cpf VARCHAR(14) UNIQUE NOT NULL,senha_hash VARCHAR(255) NOT NULL,perfil ENUM('ADMIN','ASSOCIADO') NOT NULL DEFAULT 'ASSOCIADO',status_financeiro ENUM('EM_DIA','DEVEDOR','DESFILIADO') NOT NULL DEFAULT 'EM_DIA',matricula VARCHAR(40) UNIQUE NOT NULL,data_filiacao DATE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE mensalidades (id INT AUTO_INCREMENT PRIMARY KEY,associado_id INT NOT NULL,mes_referencia TINYINT NOT NULL,ano_referencia SMALLINT NOT NULL,valor DECIMAL(10,2) NOT NULL,data_vencimento DATE NOT NULL,data_pagamento DATE NULL,forma_pagamento VARCHAR(40),status_pagamento ENUM('PAGO','PENDENTE','CANCELADO') DEFAULT 'PENDENTE',origem ENUM('MANUAL','ECONSIG','SEPLAG') DEFAULT 'MANUAL',UNIQUE KEY competencia(associado_id,mes_referencia,ano_referencia),FOREIGN KEY(associado_id) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE audit_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY,usuario_id INT NULL,acao VARCHAR(80) NOT NULL,tabela VARCHAR(80),registro_id INT,dados_antigos_json JSON,dados_novos_json JSON,ip_origem VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE SET NULL);
INSERT INTO usuarios(nome,email,cpf,senha_hash,perfil,status_financeiro,matricula,data_filiacao) VALUES ('Administrador Nexus','admin@nexus.com','000.000.000-00', '$2y$argon2id$v=19$m=65536,t=4,p=1$YWRtaW5zaWRlMTIzNDU2Nzg5$Q5qM8lFQ3E3ZJv5O3Q8Z0j8S2pQ2J7w4x6D9b8q5x4A','ADMIN','EM_DIA','ADMIN-001',CURDATE()),('Ana Silva','111.222.333-44','111.222.333-44', '$2y$argon2id$v=19$m=65536,t=4,p=1$YWRtaW5zaWRlMTIzNDU2Nzg5$Q5qM8lFQ3E3ZJv5O3Q8Z0j8S2pQ2J7w4x6D9b8q5x4A','ASSOCIADO','EM_DIA','NEX-1001',CURDATE()),('Bruno Costa','555.666.777-88','555.666.777-88', '$2y$argon2id$v=19$m=65536,t=4,p=1$YWRtaW5zaWRlMTIzNDU2Nzg5$Q5qM8lFQ3E3ZJv5O3Q8Z0j8S2pQ2J7w4x6D9b8q5x4A','ASSOCIADO','DEVEDOR','NEX-1002',CURDATE());
INSERT INTO mensalidades(associado_id,mes_referencia,ano_referencia,valor,data_vencimento,data_pagamento,status_pagamento) SELECT id,MONTH(CURDATE()),YEAR(CURDATE()),35.00,CURDATE(),CASE WHEN matricula='NEX-1001' THEN CURDATE() END,CASE WHEN matricula='NEX-1001' THEN 'PAGO' ELSE 'PENDENTE' END FROM usuarios WHERE perfil='ASSOCIADO';